/* Topic coverage adapted from the three public Englinks AI sections.
   Russian instructions are independently written for English.tools. */
window.englishAiLibrary = [
  {id:'proofread',group:'writing',title:'Разобрать свой текст',description:'Исправления с объяснениями, чтобы понять, что поменялось и почему.',fields:['text'],task:'Проверь английский текст ниже. Сначала покажи исправленную версию, сохранив смысл и авторский голос. Затем разбери до пяти полезных правок: исходная фраза, новый вариант, причина. Разделяй ошибки и необязательные стилистические улучшения. В конце предложи одно короткое упражнение на повторяющуюся ошибку. Текст для проверки: {text}'},
  {id:'rewrite-tones',group:'writing',title:'Одна фраза — три интонации',description:'Сравните нейтральное, разговорное и выразительное звучание.',fields:['sentence'],task:'Переформулируй английскую фразу в трёх регистрах: официальном, дружеском и творческом. Не меняй фактический смысл. После каждого варианта объясни, где он уместен и какие слова создают нужный тон. Фраза: {sentence}'},
  {id:'email',group:'writing',title:'Написать письмо',description:'Письмо конкретному адресату с понятной темой и нужным тоном.',fields:['recipient','subject','tone'],task:'Помоги написать английское письмо. Адресат: {recipient}. Задача письма: {subject}. Тон: {tone}. Если не хватает важной информации, задай один уточняющий вопрос. Составь тему, приветствие, основной текст и завершение. Не выдумывай имена, даты или обещания. Объясни три полезных выражения из письма.'},
  {id:'essay',group:'writing',title:'Обсудить плюсы и минусы',description:'План и пример небольшого эссе с аргументами с обеих сторон.',fields:['topic'],task:'Помоги разобрать тему «{topic}» в английском эссе. Сначала составь план: вступление, два аргумента за, два против, вывод. Потом покажи пример до 220 слов. Не выдумывай исследования и статистику. Выдели связки между аргументами, объясни их и предложи мне написать свой абзац.'},
  {id:'interactive-dialogue',group:'daily',title:'Разговор по одной реплике',description:'Собеседник ждёт вашего ответа и продолжает диалог по ситуации.',fields:['scenario'],task:'Давай разыграем разговор на английском: {scenario}. Ты собеседник, я отвечаю сам. Начни с одной короткой реплики и остановись. Не пиши мои ответы и не показывай весь диалог заранее. Подстраивай продолжение под мои слова. После шести моих ответов дай краткую обратную связь и предложи повторить трудную реплику.'},
  {id:'reading-story',group:'daily',title:'История под ваш уровень',description:'Короткое чтение на интересную тему и вопросы на понимание.',fields:['topic','length'],task:'Напиши английскую историю на тему «{topic}», объём: {length}. Используй лексику моего уровня и понятный сюжет. Затем задай три вопроса на понимание, не показывая ответы, и подожди моего ответа на первый. После чтения объясни до пяти полезных выражений из истории.'},
  {id:'culture',group:'daily',title:'Культура и этикет',description:'Как вежливо общаться в другой стране без стереотипов.',fields:['country','scenario'],task:'Объясни, как вести разговор в стране «{country}» в ситуации «{scenario}». Отделяй распространённые нормы от различий между людьми и регионами, избегай стереотипов. Дай пять английских фраз и два примера неловких формулировок с более удачными вариантами. Если не уверен в местной норме, прямо скажи об этом.'},
  {id:'confidence',group:'daily',title:'Говорить увереннее',description:'Небольшая тренировка, если мешают паузы или страх ошибки.',fields:['difficulty'],task:'Помоги мне увереннее говорить по-английски. Что мешает: {difficulty}. Предложи три выполнимых действия и одну тренировку на пять минут. Начни тренировку с простого вопроса, дождись моего ответа. Не требуй безошибочной речи: оцени, понятен ли смысл, и дай фразы, чтобы попросить время или уточнение.'},
  {id:'grammar-compare',group:'vocabulary',title:'Два правила, которые путаются',description:'Различия на похожих примерах и короткая проверка понимания.',fields:['rule1','rule2'],task:'Сравни {rule1} и {rule2}. Объясни разницу простыми словами и покажи три пары английских примеров, в которых выбор формы меняет смысл. Не придумывай абсолютное правило, если есть исключения. Затем дай три задания по одному, дожидаясь моего ответа и объясняя выбор.'},
  {id:'word-study',group:'vocabulary',title:'Разобрать новое слово',description:'Значение, близкие слова, противоположности и употребление.',fields:['word'],task:'Объясни английское слово «{word}» для моего уровня. Дай основное значение, произношение в IPA, два подходящих синонима и антоним, если он существует. Покажи четыре коротких примера в разных ситуациях и предупреди о типичной ошибке употребления. Предложи мне составить своё предложение.'},
  {id:'quiz',group:'vocabulary',title:'Тест по одной задаче',description:'Вопросы по выбранной теме с обратной связью после ответа.',fields:['topic','quiztype'],task:'Проведи интерактивный английский тест: тема «{topic}», формат «{quiztype}». Всего пять вопросов. Показывай только один вопрос за раз и жди моего ответа. После ответа объясняй правильный вариант и причину ошибки. В конце назови две темы для повторения и дай одно дополнительное задание.'},
  {id:'idiom-topic',group:'vocabulary',title:'Идиомы по теме',description:'Выражения с примерами и пояснением, где они звучат уместно.',fields:['topic'],task:'Подбери пять распространённых английских идиом на тему «{topic}». Для каждой объясни смысл, разговорный или нейтральный регистр, покажи короткий пример и более простой способ сказать то же самое. Не выдавай редкое выражение за повседневное. Затем попроси меня выбрать одну идиому и придумать ситуацию с ней.'},
  {id:'interview',group:'business',title:'Собеседование на английском',description:'Интервью по вашей роли, вопросы и разбор собственных ответов.',fields:['job','experience'],task:'Ты проводишь собеседование на позицию «{job}». Мой опыт: {experience}. Задавай по одному вопросу на английском и дожидайся ответа. После пяти ответов разберём ясность, структуру и язык. Не выдумывай мой опыт и достижения. Помоги переформулировать один ответ, сохранив только сообщённые мной факты.'},
  {id:'professional-tone',group:'business',title:'Сделать текст деловым',description:'Нейтральная рабочая формулировка без лишнего канцелярита.',fields:['text'],task:'Перепиши английский текст в ясном деловом стиле. Сохрани факты, просьбы и степень уверенности; не добавляй обещаний. Покажи исходные разговорные выражения и их рабочие варианты, объясни разницу в тоне. Текст: {text}'},
  {id:'industry-words',group:'business',title:'Английский для вашей сферы',description:'Термины и рабочие выражения, которые можно сразу использовать.',fields:['industry'],task:'Подбери десять английских слов и устойчивых выражений для сферы «{industry}», подходящих моему уровню. Для каждого дай значение и короткий рабочий пример. Отделяй общую лексику от узких терминов. Заверши мини-ситуацией, в которой я использую три выражения, и дождись моего ответа.'},
  {id:'meeting',group:'business',title:'Подготовить встречу',description:'Повестка, время и фразы для ведения рабочего разговора.',fields:['subject','duration','participants'],task:'Составь английскую повестку встречи на тему «{subject}». Длительность: {duration}. Участники: {participants}. Распредели время между вступлением, вопросами, обсуждением и решениями. Добавь фразы для начала, передачи слова, уточнения и завершения. Не придумывай решения за участников. Покажи, как вежливо вернуть разговор к теме.'},
  {id:'role-play',group:'skills',title:'Ролевая практика',description:'Задайте роли, цель и способ исправления ошибок.',fields:['scenario','yourrole','airole','goal','formality','correction'],task:'Проведи ролевой разговор на английском. Ситуация: {scenario}. Моя роль: {yourrole}. Твоя роль: {airole}. Мне нужно: {goal}. Регистр: {formality}. Исправления: {correction}. Начни с одной реплики, дождись моего ответа и не отвечай за меня. Если включены исправления после каждой реплики, сначала коротко исправь важную ошибку и продолжи разговор. При разборе в конце дай обратную связь после шести моих ответов.'},
  {id:'situation-guide',group:'skills',title:'Фразы для ситуации',description:'Подготовьтесь к отелю, аэропорту, магазину или другой встрече.',fields:['scenario'],task:'Подготовь меня к ситуации «{scenario}» на английском. Дай шесть нужных фраз: начало разговора, просьба, уточнение, проблема, подтверждение и завершение. Покажи короткий образец диалога с переводом. Затем начни похожую ситуацию со мной, задав только первую реплику.'},
  {id:'everyday-phrases',group:'skills',title:'Повседневные фразы',description:'Живые выражения для разговора на выбранную тему.',fields:['topic'],task:'Подбери восемь естественных английских фраз для повседневного разговора на тему «{topic}». Укажи значение, тон и пример ответа собеседника. Объясни, какие фразы разговорные. Предложи упражнение: я выбираю две фразы и продолжаю короткий диалог. Начни с одной реплики.'},
  {id:'slang',group:'skills',title:'Разобраться в сленге',description:'Что означает услышанная фраза и в каком общении она подходит.',fields:['phrase','context'],task:'Объясни английское сленговое выражение «{phrase}». Контекст: {context}. Разбери значение, региональные особенности, степень грубости и ситуации, в которых оно неуместно. Если без контекста возможны разные значения, покажи их. Дай нейтральную альтернативу и два примера. Не придумывай происхождение.'},
  {id:'idiom-deep',group:'skills',title:'Понять конкретную идиому',description:'Смысл, пример и близкое русское выражение.',fields:['phrase'],task:'Разбери английскую идиому «{phrase}». Объясни переносный смысл, покажи два примера и близкое русское выражение, если оно есть. Отдели буквальный перевод от значения. Происхождение упоминай только если уверен; иначе скажи, что оно не установлено. В конце предложи мне использовать идиому в одной реплике.'},
  {id:'phrasal-verbs',group:'skills',title:'Фразовый глагол без путаницы',description:'Значения, разделяемость и местоимения на коротких примерах.',fields:['phrase'],task:'Разбери фразовый глагол «{phrase}». Выбери до трёх частых значений, покажи примеры. Для каждого укажи, нужен ли объект и можно ли разделять глагол и частицу. Отдельно объясни положение местоимения, когда это применимо. Дай два задания с пропусками по одному и жди моего ответа.'},
  {id:'collocations',group:'skills',title:'С чем сочетается слово',description:'Словосочетания, которые помогают звучать естественнее.',fields:['word'],task:'Покажи восемь естественных сочетаний с английским словом «{word}». Сгруппируй их по смыслу, дай перевод и короткий пример. Сравни два частых ошибочных сочетания с правильными вариантами. Не составляй список только по внешней похожести. Попроси меня написать две фразы с новыми сочетаниями.'},
  {id:'word-deep',group:'skills',title:'Значения и оттенки слова',description:'Когда слово подходит, а когда лучше выбрать близкий вариант.',fields:['word','context'],task:'Подробно разбери английское слово «{word}». Контекст: {context}. Покажи частые значения, эмоциональный оттенок, регистр и два близких слова с различиями. Дай примеры в подходящих ситуациях и один пример, где слово звучит неестественно. Заверши вопросом, чтобы я выбрал правильное слово в новом контексте.'},
  {id:'vocabulary-builder',group:'skills',title:'Словарь под вашу тему',description:'Небольшая порция новой лексики и практика вместо длинного списка.',fields:['topic'],task:'Составь мини-словарь из семи английских слов или выражений на тему «{topic}». Выбери лексику моего уровня, дай перевод и по одному короткому примеру. Затем проведи три задания на применение, по одному за раз. Не показывай ответ до моей попытки. В конце напомни выражения, с которыми возникли трудности.'},
  {id:'grammar-guide',group:'skills',title:'Объяснить правило',description:'Понятная схема, примеры и упражнение на применение.',fields:['topic'],task:'Объясни английское правило «{topic}» простыми словами. Покажи, зачем оно нужно, схему образования, три примера и типичную ошибку. Если правило имеет исключения, обозначь основные. Потом дай одно задание на применение и дождись моего ответа. При ошибке подскажи, но не отвечай за меня сразу.'},
  {id:'dialogue-writer',group:'scenarios',title:'Написать диалог',description:'Персонажи, место, тон и нужные слова в одном разговоре.',fields:['topic','characters','location','tone','formality','length','targetwords'],task:'Напиши английский диалог на тему «{topic}». Персонажи: {characters}. Место: {location}. Настроение: {tone}. Регистр: {formality}. Длина: {length}. Слова, которые нужно использовать: {targetwords}. Реплики должны естественно продолжать друг друга и соответствовать моему уровню. После диалога объясни три полезные фразы и предложи прочитать одну роль самостоятельно.'},
  {id:'story-writer',group:'scenarios',title:'История с вашими персонажами',description:'Выберите жанр, настроение и лексику для собственного чтения.',fields:['topic','characters','genre','tone','length','targetwords'],task:'Напиши английскую историю. Тема: {topic}. Персонажи: {characters}. Жанр: {genre}. Настроение: {tone}. Длина: {length}. Целевая лексика: {targetwords}. Сюжет должен быть завершённым, а язык — соответствовать моему уровню. После истории предложи три вопроса на понимание и отдельный список полезных выражений без лишних трудных слов.'},
  {id:'diary',group:'scenarios',title:'Дневник от лица персонажа',description:'Потренируйте повествование и выражение чувств на конкретном примере.',fields:['characters','topic','tone','length'],task:'Напиши английскую дневниковую запись от лица персонажа: {characters}. Событие или тема: {topic}. Настроение: {tone}. Длина: {length}. Используй первое лицо и покажи мысли, события и реакцию персонажа. Затем выдели пять выражений, подходящих для моего собственного дневника, и предложи написать три предложения о похожем дне.'},
  {id:'writing-examiner',group:'scenarios',title:'Получить обратную связь о письме',description:'Оцените понятность текста, структуру, лексику и грамматику.',fields:['text','purpose'],task:'Разбери мой английский текст с учётом задачи «{purpose}». Отдельно оцени понятность, структуру, словарный запас и грамматику по шкале от 1 до 5, объясни каждую оценку примерами. Примерный уровень CEFR обозначь как ориентир, а не результат экзамена. Покажи три приоритетные правки и улучшенную версию, сохранив мои факты. Текст: {text}'},
  {id:'business-writing',group:'scenarios',title:'Шаблон рабочего документа',description:'Письмо, отчёт или заметка для конкретной рабочей задачи.',fields:['document','purpose','recipient','tone','targetwords'],task:'Помоги подготовить английский рабочий документ. Вид документа: {document}. Задача: {purpose}. Адресат: {recipient}. Тон: {tone}. Нужные выражения: {targetwords}. Сначала покажи структуру, затем заполняемый шаблон. Отсутствующие данные обозначь квадратными скобками; не выдумывай суммы, даты, показатели или обязательства. Объясни три выражения, которые пригодятся в похожих задачах.'}
];
window.englishAiFields = {
  text:['Ваш английский текст','Вставьте текст, который хотите разобрать','textarea'],sentence:['Ваша фраза','Например, I need an answer today'],topic:['Тема','Например, путешествия или Present Perfect'],recipient:['Адресат','Например, коллега или служба поддержки'],subject:['Тема и задача','Например, уточнить дату встречи'],tone:['Тон','Например, дружелюбный, официальный или серьёзный'],scenario:['Ситуация','Например, заселение в отель'],length:['Объём','Например, короткий: около 150 слов'],country:['Страна','Например, Великобритания'],difficulty:['Что мешает говорить','Например, забываю слова и боюсь делать ошибки'],rule1:['Первое правило','Например, Past Simple'],rule2:['Второе правило','Например, Present Perfect'],word:['Слово','Например, actually'],quiztype:['Что проверяем','Например, словарь, идиомы или грамматику'],job:['Должность','Например, product designer'],experience:['Ваш опыт','Напишите только реальные факты'],industry:['Сфера','Например, маркетинг или разработка'],duration:['Время встречи','Например, 30 минут'],participants:['Участники','Например, дизайнер, менеджер и клиент'],yourrole:['Ваша роль','Например, покупатель'],airole:['Роль ИИ','Например, продавец'],goal:['Ваша цель','Например, вернуть неподходящую покупку'],formality:['Стиль общения','Нейтральный, разговорный или официальный'],correction:['Когда исправлять','В конце, после каждой реплики или без исправлений'],phrase:['Фраза или выражение','Например, put off или a piece of cake'],context:['Контекст','Например, фраза из сериала; можно оставить пустым'],characters:['Персонажи','Например, двое друзей и их характеры'],location:['Место','Например, кафе в Лондоне'],targetwords:['Нужные слова','Например, could, recommend, instead; можно оставить пустым'],genre:['Жанр','Например, приключение, комедия или детектив'],purpose:['Задача текста','Например, объяснить проблему клиенту'],document:['Вид документа','Например, письмо, краткий отчёт или предложение']
};
